import{z as n,x as s,o as e,c as B,q as l,j as o,D as E,d as r,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"受控生成的进阶主题","description":"","frontmatter":{"title":"受控生成的进阶主题","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-controlled-advanced.md","filePath":"llm/dec-controlled-advanced.md","lastUpdated":1791063341000}'),d={name:"llm/dec-controlled-advanced.md"};function p(m,a,c,h,D,C){const t=s("Mermaid");return e(),B("div",null,[a[2]||(a[2]=l('<h1 id="受控生成的进阶主题" tabindex="-1">受控生成的进阶主题 <a class="header-anchor" href="#受控生成的进阶主题" aria-label="Permalink to &quot;受控生成的进阶主题&quot;">​</a></h1><div class="epigraph"><p>属性控制有两条路：把判别器的梯度灌进每一步的隐状态，或把约束编成掩码挡在采样前；前者软而贵，后者硬而便宜。</p><footer>—— Dathathri et al., Plug and Play Language Models, ICLR 2020；掩码一路见 Willard &amp; Louf, arXiv:2307.09702</footer></div><p><a href="/llm/spec-map">上一课</a>把投机解码收束成一张决策单，回答的是「快」。本课程回答「听话」：让输出服从结构、词法、属性与业务语义，并把它做成服务。基础课已经把 token 级掩码讲透：<a href="/llm/constrained-decoding">约束解码</a>的自动机、<a href="/llm/grammar-decode">文法约束</a>的下推机、<a href="/llm/json-schema-decode">JSON Schema</a> 的产品契约、<a href="/llm/regex-constrained-decode">正则约束</a>的活前缀，以及<a href="/llm/structured-output-overhead">结构化输出的开销</a>。本课补一张总图：控制面按什么分层、各层付出什么代价，本课程后面各课在图上的位置。后课默认你已经知道：掩码改的是支撑集，不是权重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文法掩码保证「输出能过解析器」，但产品清单上的约束大多不在文法里：摘要不得整句照抄原文，文案必须提到品牌词，回复语气要正式，字段值要来自检索命中的实体。这些约束住在不同的层：有的采样参数就能碰，有的能编成逐步掩码，有的需要一个判别器在每步打分，有的只能靠生成后的执行验证。全塞进 prompt 是软的：模型可以听见但不服从；全编成文法是做不到的：「语气正式」没有上下文无关文法。缺口是分层——每层有明确的保证强度、每步成本与失败模式，工程上按需选层、按层组合。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四层，硬度递减、语义深度递增：</p><ol><li><strong>采样参数</strong>：温度与核采样改变分布形状，不承诺任何结构，成本为零。它是所有上层控制都要穿过的底座，见 <a href="/llm/sampling-temperature-topp">Temperature / Top-k / Top-p</a>。</li><li><strong>词法与结构约束</strong>：正则、JSON Schema、CFG 编成掩码，硬保证输出属于编译后的语言。<span class="marginnote">术语翻译：「掩码」就是每步生成前把「现在绝对不许出现的 token」的概率清零，模型只能从剩下的候选里挑；「支撑集」指概率不为零的候选集合。掩码不改模型权重，只在出口处拦截——所以它给的是硬保证，代价是分布被截断。</span>基础课已讲语义；本课程后面三课写它的工程化。</li><li><strong>属性引导</strong>：判别器或能量项在每步改写 logits。PPLM 对隐状态做梯度更新再重排分布；FUDGE 训练一个「未来判别器」，每步为若干候选方向各估一次属性概率，把加权后的 logits 混回主干。软保证：倾向属性，不禁止违规。</li><li><strong>语义验证</strong>：生成后跑校验器、单测或检索比对，不合格重采样或重生成，等价于拒绝采样，见 <a href="/llm/best-of-n">Best-of-N</a>。</li></ol>',8)),(e(),o(i,null,{default:E(()=>[A(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E4%B8%8E%E7%BA%A6%E6%9D%9F%E6%B8%85%E5%8D%95%22%5D%20--%3E%20CL%7B%22%E7%BA%A6%E6%9D%9F%E4%BD%8F%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%22%7D%0A%20%20CL%20--%3E%7C%E9%A3%8E%E6%A0%BC%7C%20S1%5B%22%E9%87%87%E6%A0%B7%E5%8F%82%E6%95%B0%22%5D%0A%20%20CL%20--%3E%7C%E7%BB%93%E6%9E%84%7C%20S2%5B%22%E6%96%87%E6%B3%95%E6%8E%A9%E7%A0%81%22%5D%0A%20%20CL%20--%3E%7C%E5%B1%9E%E6%80%A7%7C%20S3%5B%22%E5%88%A4%E5%88%AB%E5%99%A8%E5%BC%95%E5%AF%BC%22%5D%0A%20%20CL%20--%3E%7C%E8%AF%AD%E4%B9%89%7C%20S4%5B%22%E4%BA%8B%E5%90%8E%E9%AA%8C%E8%AF%81%E4%B8%8E%E9%87%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20S2%20--%3E%20ENG%5B%22%E6%9C%AC%E8%AF%BE%E7%A8%8B%EF%BC%9A%E7%BC%96%E8%AF%91%E3%80%81%E7%BC%93%E5%AD%98%E3%80%81%E7%BB%84%E5%90%88%22%5D%0A%20%20S3%20--%3E%20S4%0A%20%20S4%20--%3E%20OUT%5B%22%E4%BA%A4%E4%BB%98%E4%B8%8E%E5%90%8E%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="硬度与代价是一对账" tabindex="-1">硬度与代价是一对账 <a class="header-anchor" href="#硬度与代价是一对账" aria-label="Permalink to &quot;硬度与代价是一对账&quot;">​</a></h3><p>掩码每步近似查表，却把分布截断到合法集；判别器每步多一次到几次前向，却保留模型的分布形状。<span class="marginnote">数字实例：掩码近似一次查表，开销几乎为零；而判别器每步加一次前向，decode 每步本来就要跑一遍主模型——等于把这一层的成本直接翻倍。若每个候选方向都判一次（FUDGE 式），还要再乘候选数。这就是「软而贵」的账单来源。</span>选层规则：约束能写成字符串模式，就编掩码；只存在统计倾向（毒性、风格、主题），才请判别器；只有能执行的语义（代码能跑、答案能对），才走验证重采样。选反了，要么为软约束付出硬约束的分布代价，要么为硬保证支付判别器的账单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层图解释了「不这么做会错在哪」：用 prompt 编排冒充第二层，失败率随结构复杂度上升，且重试延迟方差没有上界；用大正 bias 冒充掩码，名单外仍有概率质量（<a href="/llm/logit-bias">logit bias</a> 的边界）；用判别器冒充验证器，属性分高不等于语义正确。</p>',4)),(e(),o(i,null,{default:E(()=>[A(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20W1%5B%22%E7%94%A8%20prompt%20%E8%AF%AD%E6%B0%94%E5%86%92%E5%85%85%E7%BB%93%E6%9E%84%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20F1%5B%22%E5%A4%8D%E6%9D%82%E5%BA%A6%E9%AB%98%E6%97%B6%E5%A4%B1%E8%B4%A5%E7%8E%87%E4%B8%8A%E5%8D%87%EF%BC%8C%E9%87%8D%E8%AF%95%E5%BB%B6%E8%BF%9F%E6%97%A0%E4%B8%8A%E7%95%8C%22%5D%0A%20%20W2%5B%22%E7%94%A8%E5%A4%A7%20logit%20bias%20%E5%86%92%E5%85%85%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20F2%5B%22%E5%90%8D%E5%8D%95%E5%A4%96%E7%9A%84%20token%20%E4%BB%8D%E6%9C%89%E6%9C%BA%E4%BC%9A%E8%A2%AB%E9%87%87%E5%87%BA%22%5D%0A%20%20W3%5B%22%E7%94%A8%E5%88%A4%E5%88%AB%E5%99%A8%E5%B1%9E%E6%80%A7%E5%88%86%E5%86%92%E5%85%85%E8%AF%AD%E4%B9%89%E9%AA%8C%E8%AF%81%22%5D%20--%3E%20F3%5B%22%E5%B1%9E%E6%80%A7%E5%88%86%E9%AB%98%20%E2%89%A0%20%E8%AF%AD%E4%B9%89%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20F1%20--%3E%20M%5B%22%E5%9B%9E%E5%88%B0%E5%88%86%E5%B1%82%EF%BC%9A%E6%AF%8F%E5%B1%82%E5%8F%AA%E5%85%91%E7%8E%B0%E8%87%AA%E5%B7%B1%E7%9A%84%E4%BF%9D%E8%AF%81%22%5D%0A%20%20F2%20--%3E%20M%0A%20%20F3%20--%3E%20M%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p><span class="marginnote">这张图把三种最常见的「拿软的冒充硬的」并排放在一起。共同病因是错把「倾向」当「保证」：prompt 是建议、bias 是倾斜、属性分是打分，三者都留有失败概率；只有掩码与可执行验证才给得出「绝不超过某集合」式的承诺。</span></p><p>反过来，「必须出现某关键词」丢给纯掩码也不对：关键词可以出现在未来任意位置，这不是有限状态的「当前该写什么」。NeuroLogic 一线的工作专门处理这种前瞻约束——允许先写、对违约的未来加启发式惩罚，属于第三层的能量思路。</p><p><span class="marginnote">引导的账单不小：PPLM 每步对候选做数次梯度更新，FUDGE 为每个未来假设各跑一次判别前向。把第三层当免费旋钮，是 decode 预算最常见的事故。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>第三层是另一个攻击面：判别器是被塞进解码环路的第二个模型，它自己的偏置与被绕过的方式都算进产品风险。软引导会偏离语言流形，<a href="/llm/cfg-llm">CFG 课</a>对外推的警告同构。掩码层保证结构合法但不保证事实正确，这是基础课的老边界；<span class="marginnote">常见误区：拿到一份 100% 能通过 JSON 解析的输出，就以为模型「听话了」。语法合法与内容正确是两回事——完全合格的 JSON 里照样可以装着编造的字段值。结构层管「格式不崩」，事实层要靠检索比对或事后验证另管。</span>越往上层走，保证越弱、成本越贵，验收口径越要提前钉死。本课只钉分层地图；编译怎么做、约束怎么叠、栈怎么排，交给后面各课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>受控生成四层：采样参数、文法掩码、判别器引导、事后验证；硬度递减、语义深度递增。</li><li>能写成字符串模式的用掩码，统计倾向用判别器，可执行的语义用验证重采样。</li><li>软引导保留分布形状但每步多付前向；硬掩码便宜但把分布截断在合法集。</li><li>「关键词必现」这类前瞻约束属于能量与惩罚思路，不是有限状态能表达的。</li><li>本课程后续：编译优化、缓存复用、多约束组合，再转服务侧的栈、停止、流式与账单。</li><li>出处：Dathathri et al., PPLM, ICLR 2020；Yang &amp; Klein, FUDGE, NAACL 2021；词法前瞻见 Lu et al., NeuroLogic A*esque, 2021；掩码一路见 Willard &amp; Louf, arXiv:2307.09702。</li></ul>',7))])}const f=n(d,[["render",p]]);export{_ as __pageData,f as default};
